constexpr int kCoreB = 128;               // 8x8 bf16 core matrix
constexpr int kQMBlockB = 1024;           // 8 k-cores
constexpr int kQDimTileB = 16 * kQMBlockB;

constexpr int kKvDimCoreB = 2 * kCoreB + 16;      // 2 key-cores + pad
constexpr int kKvDimCores = kQkDim / 8;           // 72
constexpr int kKvBufB = kKvDimCores * kKvDimCoreB;

constexpr int kPMBlockB = 256;            // 2 key-cores
constexpr int kPB = 16 * kPMBlockB;

