__device__ __forceinline__ unsigned int pack_bf16(float x, float y) {
  const __nv_bfloat162 h = __floats2bfloat162_rn(x, y);
  return *reinterpret_cast<const unsigned int*>(&h);
}

// Stage 16 selected KV rows (one 16-key tile) into the blocked layout.
// Row "'`r` element `c` lands at (c/8)*272 + (r/8)*128 + (r%8)*16 + (c%8)*2.
__device__ __forceinline__ void gather_tile(Shared& sm, const bf16* __restrict__ kv,
                                            const int* __restrict__ idx_row, int buf, int tid,
                                            int tokens) {
  unsigned char* dst = sm.kv[buf];
  constexpr int kChunks = kKeys * (kQkDim / 8);  // 16 * 72
  #pragma unroll
  for (int j = 0; j < (kChunks + kThreads - 1) / kThreads; ++j) {
    const int c = tid + j * kThreads;
    if (c >= kChunks) break;
    const int r = c / (kQkDim / 8);
    const int dc = c % (kQkDim / 8);
    int row = idx_row[r];
    row = (row < 0) ? 0 : (row >= tokens ? tokens - 1 : row);
    __pipeline_memcpy_async(dst + dc * kKvDimCoreB + (r >> 3) * kCoreB + (r & 7) * 16,
                            kv + static_cast<size_t>(row) * kQkDim + dc * 8, 16);
  }
  if (tid < kKeys) sm.idx[buf][tid] = idx_row[tid];
  if (tid == 0) {
    int ok = 1;
    #pragma unroll
    for (int k = 0; k < kKeys; ++k) {
      const int v = idx_row[k];
      ok &= (v >= 0 && v < tokens);
    }
    sm.allvalid[buf] = static_cast<unsigned char>(ok);
  }
}

__global__ void __launch_bounds__(kThreads, 1)
sparse_mla_kernel(const bf16* __restrict__ q, const bf16* __restrict__ kv,
                  const int* __restrict__ indices, bf16* __restrict__ out,
                  float* __restrict__ maxlog, float* __restrict__ lse, int tokens) {
  extern __shared__ __align__(128) unsigned char smem_raw[];
  Shared& sm = *reinterpret_cast<Shared*>(smem_raw);

  const int tok = blockIdx.x;
  const int tid = threadIdx.x;
  const int wg = tid >> 7;
  const int tw = tid & 127;
  const int warp = tw >> 5;
  const int lane = tw & 31;
  const int l4 = lane & 3;
  const int brow = warp * 16 + (lane >> 2);
  const int* idx_base = indices + static_cast<size_t>(tok) * kTopk;

  // ---- load Q (128 heads x 576) once; 8 rows x 4 chunk pairs per warp pass ----
  {
    const bf16* qrow = q + static_cast<size_t>(tok) * kHeads * kQkDim;
    const int a = lane >> 3;
    const int b = lane & 7;
    #pragma unroll
    for (int s = 0; s < 18; ++s) {
      const int half = s & 1;
      const int t = s >> 1;
      const int dst = t * kQDimTileB + (half * 8 + warp) * kQMBlockB + a * 256 + b * 16;
      const bf16* src = qrow + static_cast<size_t>(half * 64 + warp * 8 + b) * kQkDim + (t * 4 + a) * 16;
      __pipeline_memcpy_async(sm.q + dst, src, 16);
      __pipeline_memcpy_async(sm.q + dst + kCoreB, src + 8, 16);
    }
    __pipeline_commit();
    __pipeline_wait_prior(0);
    __syncthreads();
  }

  // ---- software pipeline: 4 KV stages, gather issued kBuffs-1 tiles ahead ----
  #pragma unroll
  for (int u = 0; u < kBuffs - 1; ++u) {
    gather_tile(sm, kv, idx_base + u * kKeys, u, tid, tokens);
    __pipeline_commit();
  }

  float o[128];
  #pragma unroll
  for (int i = 0; i < 128; ++i) o[i] = 0.0f;
  float m0 = -INFINITY, m1 = -INFINITY, l0 = 0.0f, l1 = 0.0f;

  for (int t = 0; t < kTiles; ++t) {
    const int buf = t & (kBuffs - 1);
    __pipeline_wait_prior(kBuffs - 2);
    __syncthreads();
    if (t + kBuffs - 1 < kTiles) {
      const int u = t + kBuffs - 1;
      gather_tile(sm, kv, idx_base + u * kKeys, u & (kBuffs - 1), tid, tokens);
    }
    __pipeline_commit();

    // ---- QK: 9 dim tiles x 4 k-steps of m64n16k16 ----
    float s[8];
    {
      const uint32_t qa = smem_addr(sm.q) + wg * (8 * kQMBlockB);
      const uint32_t kva = smem_addr(sm.kv[buf]);
      wgmma_fence();
      #pragma unroll
      for (int dt = 0; dt < kDimTiles; ++dt) {
        #pragma unroll
        for (int st = 0; st < 4; ++st) {
          const uint64_t da = mk_desc(qa + dt * kQDimTileB + st * 2 * kCoreB, kCoreU, kQMBlockU);
          const uint64_t db = mk_desc(kva + (dt * 8 + st * 2) * kKvDimCoreB, kKvDimCoreU, kKvKeyCoreU);
          qk_mma(s, da, db, (dt | st) != 0);
        }
      }
      wgmma_commit();
      wgmma_wait<0>();
    }

    // ---- online softmax ----
    if (sm.allvalid[buf] == 0) {
      #pragma unroll
      for (int i = 0; i < 8; ++i) {
        const int col = 8 * (i >> 2) + 2 * l4 + (i & 1);
        const int v = sm.idx[buf][col];
        if (v < 0 || v >= tokens) s[i] = -INFINITY;
      }
    }
    float tm0 = fmaxf(fmaxf(s[0], s[1]), fmaxf(s[4], s[5]));
    float tm1 = fmaxf(fmaxf(s[2], s[3]), fmaxf(s[6], s[7]));
    tm0 = fmaxf(tm0, __shfl_xor_sync(0xffffffffu, tm0, 1));
    tm0 = fmaxf(tm0, __shfl_xor_sync(0xffffffffu, tm0, 2));
    tm1 = fmaxf(tm1, __shfl_xor_sync(0xffffffffu, tm1, 1));
    tm1 = fmaxf(tm1, __shfl_xor_sync(0xffffffffu, tm1, 2));

    const float nm0 = fmaxf(m0, tm0);
    const float nm1 = fmaxf(m1, tm1);
    const float c0 = (nm0 > m0) ? exp2f((m0 - nm0) * kScaleLog2e) : 1.0f;
    const float c1 = (nm1 > m1) ? exp2f((m1 - nm1) * kScaleLog2e) : 1.0f;
    m0 = nm0;
    m1 = nm1;

    float p[8];
    #pragma unroll
    for (int i = 0; i < 8; ++i) {
      const float mm = ((i & 2) == 0) ? nm0 : nm1;
      p[i] = exp2f((s[i] - mm) * kScaleLog2e);
    }
    float rs0 = (p[0] + p[1]) + (p[4] + p[5]);
    float rs1 = (p[2] + p[3]) + (p[6] + p[7]);
    rs0 += __shfl_xor_sync(0xffffffffu, rs0, 1);
    rs0 += __shfl_xor_sync(0xffffffffu, rs0, 2);
    rs1 += __shfl_xor_sync(0xffffffffu, rs1, 1);
    rs1 += __shfl_xor_sync(0xffffffffu, rs1, 2);
    l0 = l0 * c0 + rs0;
    l1 = l1 * c1 + rs1;

    if (c0 != 1.0f || c1 != 1.0f) {
      #pragma unroll
      for (int i = 0; i < 128; ++i) o[i] *= ((i & 2) == 0) ? c0 : c1;
    }

    #pragma unroll
    for (int i = 0; i < 8; i += 2) {
      const int row = brow + 8 * ((i & 2) >> 1);
      const int col = 8 * (i >> 2) + 2 * l4;
      *reinterpret_cast<unsigned int*>(sm.p + (row >> 3) * kPMBlockB + (col >> 3) * kCoreB +
                                       (row & 7) * 16 + (col & 7) * 2) = pack_bf16(p[i], p[i + 1]);
    }
    async_fence();

    // ---- PV ----
    {
      const uint64_t da = mk_desc(smem_addr(sm.p) + wg * (8 * kPMBlockB), kCoreU, kPMBlockU);
      const uint64_t db = mk_desc(smem_addr(sm.kv[buf]) + wg * 32 * kKvDimCoreB,
                                  kKvKeyCoreU, kKvDimCoreU);
      wgmma_fence();
      pv_mma(o, da, db);
      wgmma_commit();
      wgmma_wait<0>();
    }
  }

  // ---- finalize ----
  const float inv0 = (l0 > 0.0f) ? 1.0f / l0 : 0.0f;
  const float inv1 = (l1 > 0.0f) ? 1.0f / l1 : 0.0f;
  bf16* orow = out + static_cast<size_t>(tok) * kHeads * kValDim + wg * kHeadsWg * kValDim;
  #pragma unroll
  for (int i = 0; i < 128; i += 2) {
    const float iv = ((i & 2) == 0) ? inv0 : inv1;
    const int row = brow + 8 * ((i & 2) >> 1);
    const int col = wg * kValWg + 8 * (i >> 2) + 2 * l4;
    *reinterpret_cast<unsigned int*>(orow + static_cast<size_t>(row) * kValDim + col) =
        pack_bf16(o[i] * iv, o[i + 1] * iv);
  }
  if (l4 == 0) {
    float* ml = maxlog + static_cast<size_t>(tok) * kHeads + wg * kHeadsWg + brow;
    float* ls = lse + static_cast<size_t>(tok) * kHeads + wg * kHeadsWg + brow;
    ml[0] = m0 * kScale;
    ml[8] = m1 * kScale;
    ls[0] = logf(l0) + m0 * kScale;
    ls[8] = logf(l1) + m1 * kScale;
  }
}

void sparse_mla(torch::Tensor q, torch::Tensor kv, torch::Tensor indices,
                torch::Tensor output, torch::Tensor max_logits, torch::Tensor lse) {
  TORCH_CHECK(q.is_cuda() && kv.is_cuda() && indices.is_cuda(), "inputs must be CUDA");
  TORCH_CHECK(q.scalar_type() == torch::kBFloat16 && kv.scalar_type() == torch::kBFloat16,
              "q/kv must be bfloat16");
  TORCH_CHECK(indices.scalar_type() == torch::kInt32, "indices must be int32");
  TORCH_CHECK(q.dim() == 3 && q.size(1) == kHeads && q.size(2) == kQkDim, "unexpected q shape");
  TORCH_CHECK(kv.dim() == 3 && kv.size(1) == 1 && kv.size(2) == kQkDim, "unexpected kv shape");
  TORCH_CHECK(indices.dim() == 3 && indices.size(1) == 1 && indices.size(2) == kTopk,
              "unexpected indices shape");
  TORCH_CHECK(max_logits.scalar_type() == torch::kFloat32 && lse.scalar_type() == torch::kFloat32,
              "statistics must be float32");
  TORCH_CHECK(output.scalar_type() == torch::kBFloat16, "output must be bfloat16");

  const int tokens = static_cast<int>(q.size(0));
  if (tokens == 0) return;

  c10::cuda::CUDAGuard guard(q.device());
  const auto stream = c10::cuda::getCurrentCUDAStream(q.get_device()).stream();
  static bool configured = false;
  if (!configured) {
    cudaFuncSetAttribute(sparse_mla_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize,
                         static_cast<int>(sizeof(Shared)));
    configured = true;
  }
  sparse_mla_kernel<<<tokens, kThreads, sizeof(Shared), stream>>>(
      reinterpret_cast<const bf16*>(q.data_ptr()), reinterpret_cast<const bf16*>(kv.data_ptr()),
      indices.data_ptr<int>(), reinterpret_cast<bf16*>(output.data_ptr()),
      max_logits.data_ptr<float>(), lse.data_ptr<float>(), tokens);
  const cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
}

}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
  module.def("kernel", &sparse_mla);
}
