  const unsigned bits = __ballot_sync(0xffffffffu, enc_key >= 0);
  if (tid == 0) sm.allvalid[buf] = ((bits & 0xffffu) == 0xffffu);

  unsigned char* dst = sm.kv[buf];
  const char* src = reinterpret_cast<const char*>(kv);
  constexpr int kChunks = kKeys * kKvDimCores;
  constexpr int kIters = (kChunks + kThreads - 1) / kThreads;
  #pragma unroll
  for (int j = 0; j < kIters; ++j) {
    const int c = tid + j * kThreads;
    if (c >= kChunks) break;
    const int r = c / kKvDimCores;
    const int dc = c - r * kKvDimCores;
