288	        for (int st = 0; st < 4; ++st) {
289	          const uint64_t da = desc(qlo + dt * kQDimTileU + st * kKStepU, kQSlabU);
290	          const uint64_t db = desc(klo + (dt * 8 + st * 2) * kKvDimCoreU, kKvKeyCoreU);
291	          qk_mma(s, da, db, (dt | st) != 0);
292	        }
293	      }
294	      wgmma_commit();
295	
296	      // The next tile's gather overlaps this QK's tensor work: the loads only
297	      // have to land before the warp reaches the first dependent store.
298	      const int u = t + kBuffs - 1;
299	      if (u < kTiles) gather_tile(sm, kv, sm.idx + u * kKeys, u % kBuffs, tid);
300	
301	      wgmma_wait<0>();
302	    }
303	
304	    // ---- online softmax over the 16 staged keys ----
305	    if (sm.allvalid[buf] == 0) {
306	      const int* tile_enc = sm.idx + t * kKeys;
307	      #pragma unroll
308	      for (int i = 0; i < 8; ++i) {
309	        const int col = 8 * (i >> 2) + 2 * l4 + (i & 1);
310	        if (tile_enc[col] < 0) s[i] = -INFINITY;
311	      }
312	    }
313	    float tm0 = fmaxf(fmaxf(s[0], s[1]), fmaxf(s[4], s[5]));
314	    float tm1 = fmaxf(fmaxf(s[2], s[3]), fmaxf(s[6], s[7]));
315	    tm0 = fmaxf(tm0, __shfl_xor_sync(0xffffffffu, tm0, 1));
316	    tm0 = fmaxf(tm0, __shfl_xor_sync(0xffffffffu, tm0, 2));
317	    tm1 = fmaxf(tm1, __shfl_xor_sync(0xffffffffu, tm1, 1));
318	    tm1 = fmaxf(tm1, __shfl_xor_sync(0xffffffffu, tm1, 2));
319	
320	    const float nm0 = fmaxf(m0, tm0);
321	    const float nm1 = fmaxf(m1, tm1);
322	    const float c0 = (nm0 > m0) ? exp2_approx((m0 - nm0) * kScaleLog2e) : 1.0f;
323	    const float c1 = (nm1 > m1) ? exp2_approx((m1 - nm1) * kScaleLog2e) : 1.0f;
324	    m0 = nm0;
325	    m1 = nm1;
326	
327	    float p[8];
328	    #pragma unroll
329	    for (int i = 0; i < 8; ++i) {
330	      const float mm = ((i & 2) == 0) ? nm0 : nm1;
331	      p[i] = exp2_approx((s[i] - mm) * kScaleLog2e);
332	    }
333	    float rs0 = (p[0] + p[1]) + (p[4] + p[5]);
334	    float rs1 = (p[2] + p[3]) + (p[6] + p[7]);
335	    rs0 += __shfl_xor_sync(0xffffffffu, rs0, 1);
336	    rs0 += __shfl_xor_sync(0xffffffffu, rs0, 2);
337	    rs1 += __shfl_xor_sync(0xffffffffu, rs1, 1);
338	    rs1 += __shfl_xor_sync(0xffffffffu, rs1, 2);
339	    l0 = l0 * c0 + rs0;
340	    l1 = l1 * c1 + rs1;
341	
342	    if (c0 != 1.0f || c1 != 1.0f) {
343	      #pragma unroll
344	      for (int i = 0; i < 128; ++i) o[i] *= ((i & 2) == 0) ? c0 : c1;
345	    }
346	
347	    #pragma unroll
348	    for (int i = 0; i < 8; i += 2) {
349	      const int row = brow + 8 * ((i & 2) >> 1);
350	      const int col = 8 * (i >> 2) + 2 * l4;
351	      *reinterpret_cast<unsigned int*>(sm.p + wg * (8 * kPMBlockB) + (row >> 3) * kPMBlockB +
352	                                       (col >> 3) * kCoreB + (row & 7) * 16 + (col & 7) * 2) =
353	          pack_bf16(p[i], p[i + 1]);
354	    }
355	    async_fence();
356	
357	    // ---- PV: 16 keys x 256 latent columns ----
358	    {
359	      const uint32_t plo = (smem_addr(sm.p) >> 4) + wg * kPSlabOffU + (kCoreU << 16);
360	      const uint32_t vlo =
361	          (smem_addr(sm.kv[buf]) >> 4) + vhalf * kValHalfU + (kKvKeyCoreU << 16);
362	      wgmma_fence();
363	      pv_mma(o, desc(plo, kPSlabU), desc(vlo, kKvDimCoreU));
364	      wgmma_commit();
365	      wgmma_wait<0>();
366	    }
367	  }
368	
369	  // ---- finalize: row-normalize and emit this CTA's value half ----
370	  const float inv0 = (l0 > 0.0f) ? 1.0f / l0 : 0.0f;
371	  const float inv1 = (l1 > 0.0f) ? 1.0f / l1 : 0.0f;
372	  bf16* orow = out + static_cast<size_t>(tok) * kHeads * kValDim + wg * kHeadsWg * kValDim;
373	  #pragma unroll
374	  for (int i = 0; i < 128; i += 2) {
375	    const float iv = ((i & 2) == 0) ? inv0 : inv1;
376	    const int row = brow + 8 * ((i & 2) >> 1);
377	    const int col = vhalf * kValHalf + 8 * (i >> 2) + 2 * l4;
378	    *reinterpret_cast<unsigned int*>(orow + static_cast<size_t>(row) * kValDim + col) =
379	        pack_bf16(o[i] * iv, o[i + 1] * iv);
380	  }
381	  if (l4 == 0 && vhalf == 0) {
382	    float* ml = maxlog + static_cast<size_t>(tok) * kHeads + wg * kHeadsWg + brow;
383	    float* ls = lse + static_cast<size_t>(tok) * kHeads + wg * kHeadsWg + brow;
384	    ml[0] = m0 * kScale;
385	    ml[8] = m1 * kScale;
386	    ls[0] = logf(l0) + m0 * kScale;
387	    ls[8] = logf(l1) + m1 * kScale;
388	  }
389	}
390	
391	void sparse_mla(torch::Tensor q, torch::Tensor kv, torch::Tensor indices,
392	                torch::Tensor output, torch::Tensor max_logits, torch::Tensor lse) {
393	  TORCH_CHECK(q.is_cuda() && kv.is_cuda() && indices.is_cuda(), "inputs must be CUDA");
394	  TORCH_CHECK(q.scalar_type() == torch::kBFloat16 && kv.scalar_type() == torch::kBFloat16,
395	              "q/kv must be bfloat16");
396	  TORCH_CHECK(indices.scalar_type() == torch::kInt32, "indices must be int32");
397	  TORCH_CHECK(q.dim() == 3 && q.size(1) == kHeads && q.size(2) == kQkDim, "unexpected q shape");
398	  TORCH_CHECK(kv.dim() == 3 && kv.size(1) == 1 && kv.size(2) == kQkDim, "unexpected kv shape");
399	  TORCH_CHECK(indices.dim() == 3 && indices.size(1) == 1 && indices.size(2) == kTopk,
400	              "unexpected indices shape");
401	  TORCH_CHECK(output.dim() == 3 && output.size(1) == kHeads && output.size(2) == kValDim,
402	              "unexpected output shape");
403	  TORCH_CHECK(max_logits.scalar_type() == torch::kFloat32 && lse.scalar_type() == torch::kFloat32,
404	              "statistics must be float32");
405	  TORCH_CHECK(output.scalar_type() == torch::kBFloat16, "output must be bfloat16");
406	
407	  const int tokens = static_cast<int>(q.size(0));
408	  if (tokens == 0) return;
409	
410	  c10::cuda::CUDAGuard guard(q.device());
411	  const auto stream = c10::cuda::getCurrentCUDAStream(q.get_device()).stream();
412	  static bool configured = false;
413	  if (!configured) {
414	    cudaFuncSetAttribute(sparse_mla_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize,
415	                         static_cast<int>(sizeof(Shared)));
416	    configured = true;
417	  }
418	  sparse_mla_kernel<<<2 * tokens, kThreads, sizeof(Shared), stream>>>(
419	      reinterpret_cast<const bf16*>(q.data_ptr()), reinterpret_cast<const bf16*>(kv.data_ptr()),
420	      indices.data_ptr<int>(), reinterpret_cast<bf16*>(output.data_ptr()),
421	      max_logits.data_ptr<float>(), lse.data_ptr<float>(), tokens);
422	  const cudaError_t err = cudaGetLastError();
423	  TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
424	}
425	
426	}  // namespace
427	
428	PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
429	  module.def("kernel", &sparse_mla);
430	}

